import {scienceGames} from './science-games.mjs';
import {renderScience} from './science-games-ui.mjs';
import {mountCompanion} from './companion.mjs';
import {renderReflection} from './reflection-ui.mjs';
import {languages,languageFor} from './languages.mjs';
import {renderLanguage} from './languages-ui.mjs';
import {disciplines} from './disciplines.mjs';
import {areas,catalog,entriesFor,statusLabel,typeLabel,stageCount} from './catalog.mjs';
import {wordActivity} from './word-game.mjs';
import {renderWordGame} from './word-game-ui.mjs';
import {PROGRESS_KEY} from './local-progress.mjs';
import {createProgressSession} from './progress-session.mjs';
import {gardenActivity} from './garden-game.mjs';
import {renderGarden} from './garden-game-ui.mjs';
import {comparisonUnit} from './comparison-unit.mjs';
import {renderComparisonUnit} from './comparison-unit-ui.mjs';
import {getFacilitation} from './facilitation.mjs';
import {extraActivities,checkActivityAnswer} from './activities.mjs';
import {stages,shapes,checkGrouping,supplies,evaluatePlan,nextSessionPhase,storyCards,initialStoryOrder,moveStoryCard,checkStory,evidenceSources,evidenceQuestions,checkEvidence} from './logic.mjs';
const companionRoot=document.querySelector('#companion'),companionHome=document.querySelector('#companion-home');let companionController;
const stageButtons=document.querySelector('#stage-buttons');
const panel=document.querySelector('#stage-panel');
const states={};const selectedActivities={};let stage=null;let selectedArea='all';
const fresh=()=>({phase:'intro',unitPage:'connect',unitAnswers:{},unitFeedback:{},unitHints:{},extraStep:0,extraChoice:null,extraCorrect:false,hintLevel:0,rule:'color',shapes:new Set(),plan:new Set(),budget:8,challenge:false,story:[...initialStoryOrder],storyChecked:false,storyReason:false,storyChoice:null,evidenceStep:0,evidenceChoice:null,evidenceCorrect:false,evidenceDone:false,feedback:'',success:false});
const stateKey=()=>`${stage}:${selectedActivities[stage]||'original'}`;
const current=()=>states[stateKey()];
const selectedStage=()=>catalog.find(a=>a.key===stateKey());
const on=(id,event,fn)=>document.getElementById(id)?.addEventListener(event,fn);
const focus=(id)=>document.getElementById(id)?.focus();
const focusStageEntry=()=>focus(document.body.classList.contains('garden-focus')?'session-title':'stage-title');
function announce(text){document.querySelector('#app-status').textContent=text;}
function feedback(text){current().feedback=text;const el=document.querySelector('#feedback');if(el)el.textContent=text;}
function transition(action){current().phase=nextSessionPhase(current().phase,action);renderPanel();focus('session-title');}
function renderStages(){stageButtons.innerHTML=stages.map(s=>`<button type="button" class="stage-button" data-stage="${s.id}" aria-pressed="${s.id===stage}" aria-controls="stage-panel"><strong>${s.label}</strong><span>${stageCount(s.id)}</span></button>`).join('');stageButtons.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{stage=b.dataset.stage;if(stage==='5y')selectedActivities[stage]??='garden';states[stateKey()]??=fresh();renderStages();renderPanel();focusStageEntry();}));}
function renderAreas(){
 const root=document.querySelector('#area-filter');
 root.innerHTML=`<label for="area-select">02 · Elige un área</label><select id="area-select"><option value="all">Todas las áreas</option>${areas.map(a=>`<option value="${a}" ${selectedArea===a?'selected':''}>${a}</option>`).join('')}</select><p class="quiet">Acceso libre a todas las propuestas. Cambiar de etapa o área conserva tus respuestas, salvo las decisiones narrativas de Dani, que se descartan al salir.</p>`;
 on('area-select','change',event=>{selectedArea=event.target.value;renderPanel();announce(stage?`${entriesFor(stage,selectedArea).length} propuestas en ${selectedArea==='all'?'todas las áreas':selectedArea}.`:'Elige una etapa para explorar esta área.');});
}
function renderPanel(){
 companionHome.append(companionRoot);companionRoot.classList.remove('in-game');
 if(!stage){document.body.classList.remove('garden-focus');panel.innerHTML=`<div class="welcome"><span class="welcome-icon" aria-hidden="true">↗</span><div><h3 id="stage-title" tabindex="-1">Un pequeño paso empieza aquí.</h3><p>Elige una etapa para ver el objetivo, el acompañamiento y la propuesta antes de empezar. No necesitas crear una cuenta ni introducir datos.</p><p class="quiet">Las edades son orientativas. Puedes explorar otra etapa cuando lo necesites.</p></div></div>`;return;}
 const s=selectedStage(),state=current();
 if(selectedArea!=='all'){
 document.body.classList.remove('garden-focus');
 const visible=entriesFor(stage,selectedArea);
 if(!visible.some(a=>a.id===(selectedActivities[stage]||'original'))){
 panel.innerHTML=`<h3 id="stage-title" tabindex="-1">${s.label} · ${selectedArea}</h3>${catalogMarkup()}<div id="activity"></div>`;bindCatalog();return;
 }
 }
 document.body.classList.toggle('garden-focus',['garden','words'].includes(selectedActivities[stage])&&state.phase!=='intro'&&state.gardenFocus!==false);
 panel.innerHTML=`<div class="panel-head"><div><span class="pill">${s.label} · ${s.kind==='offline'?'Fuera de pantalla':'Un objetivo por reto'}</span><h3 id="stage-title" tabindex="-1">${s.title}</h3><p class="panel-copy">${s.copy}</p></div><span class="privacy-label">Sin perfiles ni registros</span></div>${catalogMarkup()}<div id="activity" class="activity"></div>`;
 bindCatalog();
 if(state.phase==='intro')renderIntro(s);else if(state.phase==='paused')renderPause(s);else if(state.phase==='finished')renderFinish(s);else renderActive(s);
}
function renderIntro(s){document.querySelector('#activity').innerHTML=`<div class="session-intro"><div><p class="eyebrow">${s.kind==='offline'?'UNA IDEA PARA QUIEN ACOMPAÑA':'ANTES DE EMPEZAR'}</p><h4 id="session-title" tabindex="-1">${s.unit}</h4><p>${s.goal}</p><ul class="session-facts"><li><span aria-hidden="true">◷</span> ${s.duration}</li><li><span aria-hidden="true">◎</span> ${s.support}</li></ul><p class="time-note">${s.kind==='offline'?'Ventana de juego orientativa y ajustable, no una recomendación clínica ni una duración que cumplir. El adulto lee la guía y aparta la pantalla. Sigue su interés y para antes si hace falta.':'Estimación de diseño orientativa y ajustable, no un tiempo ideal ni una recomendación clínica. Puedes terminar antes, pedir ayuda o hacer una pausa.'}</p></div><aside class="intention"><span class="eyebrow">UN CIERRE NATURAL</span><p>${s.kind==='offline'?'Lee la idea, guarda la pantalla y sigue su interés. No hay nada que completar aquí.':'Prueba una idea, conversa sobre lo que ocurrió y elige si hoy quieres parar. Una sola ronda también cuenta.'}</p></aside></div>${facilitationMarkup()}<div class="controls"><button type="button" class="action primary" id="start-session">${s.kind==='offline'?'Leer la guía':'Empezar este reto'} <span aria-hidden="true">→</span></button></div>`;on('start-session','click',()=>transition('start'));}
function renderActive(s){document.querySelector('#activity').innerHTML=`<div class="session-toolbar"><div><p class="eyebrow">${s.kind==='offline'?'GUÍA DEL ADULTO':'TU PEQUEÑO RETO'}</p><h4 id="session-title" tabindex="-1">${s.unit}</h4></div><div class="session-actions">${['garden','words'].includes(selectedActivities[stage])?`<button type="button" class="action secondary garden-library-toggle" id="garden-library">${current().gardenFocus===false?'Volver al juego':'Ver catálogo'}</button>`:''}<button type="button" class="action secondary" id="pause-session">Pausar</button><button type="button" class="action secondary" id="finish-session">${s.kind==='offline'?'Guardar la pantalla':'Terminar por hoy'}</button></div></div><details id="activity-companion" class="activity-companion"><summary><span class="companion-mini" aria-hidden="true">• •</span> Mi acompañante · pistas y apariencia</summary><div id="companion-host"></div></details><div id="exercise"></div>${facilitationMarkup()}`;
 on('garden-library','click',()=>{current().gardenFocus=current().gardenFocus===false;renderPanel();focus(current().gardenFocus?'session-title':'stage-title');});
 on('pause-session','click',()=>transition('pause'));on('finish-session','click',()=>transition('finish'));
 if(Object.hasOwn(scienceGames,selectedActivities[stage]))renderScience(document.querySelector('#exercise'),current(),selectedActivities[stage],()=>transition('finish'));else if(selectedActivities[stage]==='reflection')renderReflection(document.querySelector('#exercise'),()=>transition('finish'));else if(languageFor(selectedActivities[stage]))renderLanguage(document.querySelector('#exercise'),current(),selectedActivities[stage],()=>transition('finish'));else if(selectedActivities[stage]==='words')renderWordGame(document.querySelector('#exercise'),current(),()=>transition('finish'));else if(selectedActivities[stage]==='garden')renderGarden(document.querySelector('#exercise'),current(),()=>transition('finish'));else if(selectedActivities[stage]==='unit')renderComparisonUnit(document.querySelector('#exercise'),current());else if(selectedActivities[stage]==='extra')renderExtra();else if(stage==='3y')renderShapes();else if(stage==='7y')renderPlan();else if(stage==='5y')renderStory();else if(stage==='12y')renderEvidence();else renderCaregiver();
 document.querySelector('#companion-host').append(companionRoot);companionRoot.classList.add('in-game');companionController?.refresh();
}
function renderPause(s){document.querySelector('#activity').innerHTML=`<div class="rest-panel"><span class="rest-icon" aria-hidden="true">☁</span><p class="eyebrow">A TU RITMO</p><h4 id="session-title" tabindex="-1">La pausa también tiene sitio.</h4><p>Puedes moverte, mirar a tu alrededor o hacer otra cosa. No hay una cuenta atrás.</p><p class="quiet">${s.id==='reflection'?'Al pausar, las decisiones de esta historia se han descartado para proteger tu intimidad. Solo se conserva que la sesión está en pausa. Al volver empezarás otra versión de la historia; tus respuestas narrativas no se guardan en este navegador ni en una cuenta.':'Tus elecciones siguen aquí. Consulta el aviso de guardado de arriba: si indica «Guardado en este navegador», podrás volver incluso después de recargar. No se guardan en una cuenta.'}</p><div class="controls"><button type="button" class="action primary" id="resume-session">${s.id==='reflection'?'Empezar otra versión de la historia':'Volver al reto'}</button><button type="button" class="action secondary" id="finish-paused">Terminar por hoy</button><button type="button" class="action secondary" id="paused-catalog">Ver otras propuestas</button></div></div>`;on('paused-catalog','click',()=>{current().gardenFocus=false;renderPanel();focus('stage-title');announce('El reto sigue en pausa. Puedes elegir otra propuesta o etapa.');});on('resume-session','click',()=>transition('resume'));on('finish-paused','click',()=>transition('finish'));}
function renderFinish(s){document.querySelector('#activity').innerHTML=`<div class="rest-panel"><span class="rest-icon" aria-hidden="true">✳</span><p class="eyebrow">UN BUEN LUGAR PARA PARAR</p><h4 id="session-title" tabindex="-1">Por hoy está bien.</h4><p>No hace falta completar todos los pasos. Si te apetece, lleva una idea fuera de la pantalla:</p><div class="offline-idea"><strong>${s.kind==='offline'?'Juego acompañado':'Una idea para explorar'}</strong><p>${s.transfer}</p></div><p class="quiet">${s.kind==='offline'?'Usa materiales seguros, sin piezas pequeñas, y supervisión directa. Sigue su interés y para si aparece cansancio o frustración.':'Puedes contarlo hablando, señalando o dibujando. No pedimos datos personales ni evaluamos capacidades.'}</p><div class="controls"><button type="button" class="action secondary" id="restart-session">Volver a la propuesta</button><a class="button secondary" id="finished-catalog" href="#etapas">Ver otras etapas</a></div></div>`;on('finished-catalog','click',()=>{current().gardenFocus=false;document.body.classList.remove('garden-focus');});on('restart-session','click',()=>{states[stateKey()]=fresh();renderPanel();focus('session-title');});}
function feedbackMarkup(){return `<div id="feedback" class="feedback" role="status" aria-live="polite" aria-atomic="true">${current().feedback}</div>`;}
function bindFinish(){on('finish-unit','click',()=>transition('finish'));}
function closeMarkup(){return `<div class="natural-close" id="natural-close" ${current().success?'':'hidden'}><div><strong>Puedes dejarlo aquí.</strong><p>Explica tu idea hablando, señalando o en papel. No hace falta otra ronda.</p></div><button type="button" class="action primary" id="finish-unit">Cerrar este pequeño reto</button></div>`;}
function showClose(show){current().success=show;const el=document.getElementById('natural-close');if(el)el.hidden=!show;}
function renderShapes(){const st=current();document.querySelector('#exercise').innerHTML=`<p class="activity-context">Un adulto lee y acompaña. Puedes señalar las piezas y conversar.</p><fieldset><legend id="shape-rule">${st.rule==='color'?'Elige todas las piezas azules.':'Ahora cambia la regla: elige todos los círculos.'}</legend><p>No importa ${st.rule==='color'?'su forma':'su color'}. Toca una pieza para elegirla; vuelve a tocarla para quitarla.</p><div class="shape-grid">${shapes.map(s=>`<button type="button" class="choice" data-shape="${s.id}" aria-pressed="${st.shapes.has(s.id)}"><span class="shape ${s.shape} ${s.color}" aria-hidden="true"></span><span class="choice-text">${s.name}</span></button>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="check-shapes">Comprobar mi idea</button><button type="button" class="action secondary" id="hint">Quiero una pista</button><button type="button" class="action secondary" id="reset-shapes">Empezar de nuevo</button></div>${feedbackMarkup()}${closeMarkup()}<div class="controls"><button type="button" class="action secondary" id="change-rule" ${st.success&&st.rule==='color'?'':'hidden'}>Opcional: probar otra regla →</button></div><div class="transfer"><h4>De la pantalla al mundo</h4><p>Busca dos objetos grandes de la misma forma y distinto color. ¿Qué cambia si los agrupas de otra manera? La explicación se conversa, no se registra.</p></div>`;
 document.querySelectorAll('[data-shape]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.shape;st.shapes.has(id)?st.shapes.delete(id):st.shapes.add(id);b.setAttribute('aria-pressed',String(st.shapes.has(id)));document.querySelector('#change-rule').hidden=true;showClose(false);feedback('');}));
 on('check-shapes','click',()=>{const result=checkGrouping([...st.shapes],st.rule);if(result.correct){feedback(st.rule==='color'?'Encontraste las dos piezas azules. Tienen formas diferentes y comparten el color. ¿Por qué entra cada una en este grupo?':'Encontraste los dos círculos. Cambiaste la regla: ahora importa la forma. ¿Qué cambió en tu elección?');showClose(true);document.querySelector('#change-rule').hidden=st.rule!=='color';}else{feedback(st.shapes.size===0?'Todavía no hay piezas elegidas. Observa la regla y prueba con una.':result.extra.length?`Hay una pieza elegida que no sigue la regla. Busca ${st.rule==='color'?'el color azul, aunque cambie la forma':'los círculos, aunque cambie el color'}. Puedes cambiar tu selección.`:'Las piezas elegidas siguen la regla. ¿Falta alguna que también encaje?');}});
 on('hint','click',()=>feedback(st.rule==='color'?'Mira el círculo azul. ¿Qué otra pieza tiene ese mismo color? Las etiquetas también te ayudan.':'Un círculo tiene un borde redondo, sin esquinas. Hay uno de cada color.'));
 on('change-rule','click',()=>{st.rule='shape';st.shapes.clear();st.feedback='Nueva regla: elige todos los círculos.';st.success=false;renderShapes();document.querySelector('[data-shape]').focus();announce(st.feedback);});
 on('reset-shapes','click',()=>{st.rule='color';st.shapes.clear();st.feedback='Actividad reiniciada. Elige todas las piezas azules.';st.success=false;renderShapes();document.querySelector('[data-shape]').focus();announce(st.feedback);});bindFinish();
}
function renderPlan(){const st=current();document.querySelector('#exercise').innerHTML=`<span class="pill">Situación ficticia · varias soluciones</span><h4>Prepara una salida al parque</h4><p>En esta historia, saldrás con un adulto. Necesitas agua, una merienda y revisar la ruta. Lo demás es opcional.</p><div class="budget" id="budget-summary" role="status" aria-live="polite" aria-atomic="true"></div><fieldset><legend>¿Qué incluirías en tu plan?</legend><div class="supply-grid">${supplies.map(s=>`<label class="supply"><input type="checkbox" value="${s.id}" ${st.plan.has(s.id)?'checked':''}><span><strong><span aria-hidden="true">${s.icon}</span> ${s.name} · ${s.cost} fichas</strong><small>${s.description}</small></span></label>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="check-plan">Revisar mi plan</button><button type="button" class="action secondary" id="plan-hint">Una pista</button><button type="button" class="action secondary" id="reset-plan">Empezar de nuevo</button></div>${feedbackMarkup()}${closeMarkup()}<div class="controls"><button type="button" class="action secondary" id="challenge" ${st.success&&!st.challenge?'':'hidden'}>Opcional: cambiar el presupuesto →</button></div><div class="transfer"><h4>Tu decisión tiene una razón</h4><p>¿Qué priorizaste? ¿Hay otra combinación posible? Explícalo en voz alta o en papel.</p><p class="quiet">Los precios y las condiciones son inventados. Esto no es una compra ni una lista de seguridad completa.</p></div>`;
 document.querySelectorAll('.supply input').forEach(input=>input.addEventListener('change',()=>{input.checked?st.plan.add(input.value):st.plan.delete(input.value);updateBudget();document.querySelector('#challenge').hidden=true;showClose(false);feedback('');}));
 on('check-plan','click',()=>{const r=evaluatePlan([...st.plan],st.budget);const messages=[];if(r.missing.length)messages.push(`Falta resolver: ${r.missing.join(', ')}.`);if(r.overBudget)messages.push(`El plan supera el presupuesto por ${-r.remaining} fichas. ¿Qué podrías cambiar o dejar para otra ocasión?`);if(r.ready){messages.push(`Tu plan cubre lo necesario y deja ${r.remaining} fichas. No es la única solución: ¿por qué elegiste esta?`);document.querySelector('#challenge').hidden=st.challenge;showClose(true);}feedback(messages.join(' '));});
 on('plan-hint','click',()=>feedback('Empieza por lo necesario. Agua y revisar la ruta no gastan fichas. Compara las dos meriendas antes de elegir los extras.'));
 on('challenge','click',()=>{st.budget=5;st.challenge=true;st.success=false;st.feedback='Cambio de situación: ahora tienes 5 fichas. Conservamos tus elecciones para que puedas revisarlas.';renderPlan();document.querySelector('.supply input').focus();announce(st.feedback);});
 on('reset-plan','click',()=>{st.budget=8;st.challenge=false;st.plan.clear();st.success=false;st.feedback='Plan reiniciado. Tienes 8 fichas.';renderPlan();document.querySelector('.supply input').focus();announce(st.feedback);});updateBudget();bindFinish();
}
function updateBudget(){const st=current(),r=evaluatePlan([...st.plan],st.budget);document.querySelector('#budget-summary').textContent=`Presupuesto: ${st.budget} fichas · Elegido: ${r.total} · ${r.remaining>=0?'Disponibles: '+r.remaining:'Exceso: '+(-r.remaining)}`;}
function renderStory(){const st=current();document.querySelector('#exercise').innerHTML=`<p class="activity-context">Una historia inventada. Puedes leerla con ayuda y responder señalando.</p><h4>¿Qué pasó primero?</h4><p>Estos momentos están mezclados. Usa «Subir» y «Bajar» para contar qué probó Lía, qué cambió y qué ocurrió después.</p><ol class="story-list">${st.story.map((id,i)=>{const c=storyCards.find(c=>c.id===id);return `<li class="story-card"><span class="story-symbol" aria-hidden="true">${c.icon}</span><div><strong><span class="story-position">${i+1}.</span> ${c.title}</strong><p>${c.text}</p></div><div class="story-actions"><button type="button" class="move-button" data-move="${id}" data-direction="-1" aria-label="Subir: ${c.title}" ${i===0?'disabled':''}>↑ Subir</button><button type="button" class="move-button" data-move="${id}" data-direction="1" aria-label="Bajar: ${c.title}" ${i===2?'disabled':''}>↓ Bajar</button></div></li>`;}).join('')}</ol><div class="controls"><button type="button" class="action primary" id="check-story">Revisar la historia</button><button type="button" class="action secondary" id="story-hint">Una pista</button></div>${feedbackMarkup()}<fieldset id="story-reflection" class="reflection" ${st.storyChecked?'':'hidden'}><legend>¿Qué cambió Lía entre las dos pruebas?</legend><div class="answer-options"><button type="button" class="answer-option" data-reason="paper" aria-pressed="${st.storyChoice==='paper'}">La forma del mismo papel</button><button type="button" class="answer-option" data-reason="car" aria-pressed="${st.storyChoice==='car'}">El coche que colocó encima</button></div></fieldset>${closeMarkup()}`;
 document.querySelectorAll('[data-move]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.move,direction=Number(b.dataset.direction);st.story=moveStoryCard(st.story,id,direction);st.storyChecked=false;st.storyReason=false;st.storyChoice=null;st.success=false;st.feedback='';renderStory();const next=document.querySelector(`[data-move="${id}"][data-direction="${direction}"]:not(:disabled)`)||document.querySelector(`[data-move="${id}"]:not(:disabled)`);next?.focus();announce(`${storyCards.find(c=>c.id===id).title}, posición ${st.story.indexOf(id)+1} de 3.`);}));
 on('check-story','click',()=>{st.storyChecked=checkStory(st.story);document.getElementById('story-reflection').hidden=!st.storyChecked;feedback(st.storyChecked?'La historia conecta una prueba, un cambio y una nueva prueba. Ahora mira qué cambió Lía.':'Busca la primera prueba, cuando el puente todavía era plano. Después, ¿qué idea prueba Lía? Puedes mover las tarjetas.');});
 on('story-hint','click',()=>feedback('«Después de ver que se hunde» nos da una pista. El puente se hundió antes de que Lía doblara el papel.'));
 document.querySelectorAll('[data-reason]').forEach(b=>b.addEventListener('click',()=>{st.storyChoice=b.dataset.reason;document.querySelectorAll('[data-reason]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));st.storyReason=b.dataset.reason==='paper';showClose(st.storyReason);feedback(st.storyReason?'Lía cambió la forma del papel y mantuvo el mismo coche. Así pudo comparar las dos pruebas. ¿Qué otra forma te gustaría investigar?':'La historia dice que usó el mismo coche. Vuelve a mirar qué hizo con el papel.');}));bindFinish();
}
function renderEvidence(){const st=current(),q=evidenceQuestions[st.evidenceStep];document.querySelector('#exercise').innerHTML=`<div class="case-heading"><span class="pill">Caso ficticio · datos inventados</span><h4>Una nueva fuente en el colegio</h4><p>Alguien afirma: «Desde que tenemos la fuente, cada persona usa menos botellas de un solo uso». Antes de aceptar la explicación, mira qué sabemos.</p></div><div class="evidence-grid">${evidenceSources.map((s,i)=>`<article class="evidence-card"><span class="source-number">FUENTE ${i+1} · ${s.tag}</span><h5>${s.title}</h5><p>${s.body}</p></article>`).join('')}</div><div class="question-head"><span class="pill">Pregunta ${st.evidenceStep+1} de ${evidenceQuestions.length}</span><span class="quiet">Sin puntuación ni reloj</span></div><fieldset><legend id="evidence-question" tabindex="-1">${q.title}</legend><div class="answer-options">${q.options.map(o=>`<button type="button" class="answer-option" data-answer="${o.id}" aria-pressed="${st.evidenceChoice===o.id}">${o.label}</button>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="check-evidence">Revisar mi razonamiento</button></div>${feedbackMarkup()}<div class="controls"><button type="button" class="action secondary" id="next-evidence" ${st.evidenceCorrect&&st.evidenceStep<evidenceQuestions.length-1?'':'hidden'}>Seguir con otra pregunta →</button></div>${closeMarkup()}<p class="quiet">No se recopilan respuestas ni datos de estudiantes. Las reglas solo comprueban la interpretación de este caso.</p>`;
 document.querySelectorAll('[data-answer]').forEach(b=>b.addEventListener('click',()=>{st.evidenceChoice=b.dataset.answer;st.evidenceCorrect=false;st.success=false;document.querySelectorAll('[data-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#next-evidence').hidden=true;showClose(false);feedback('');}));
 on('check-evidence','click',()=>{if(!st.evidenceChoice){feedback('Elige una explicación para revisarla. Puedes releer las fuentes sin prisa.');return;}const result=checkEvidence(q.id,st.evidenceChoice);st.evidenceCorrect=result.correct;feedback(result.feedback);document.querySelector('#next-evidence').hidden=!result.correct||st.evidenceStep===evidenceQuestions.length-1;showClose(result.correct&&st.evidenceStep===evidenceQuestions.length-1);});
 on('next-evidence','click',()=>{st.evidenceStep++;st.evidenceChoice=null;st.evidenceCorrect=false;st.feedback='';renderEvidence();focus('evidence-question');});bindFinish();
}
function renderCaregiver(){const toddler=stage==='18m';document.querySelector('#exercise').innerHTML=`<p class="eyebrow">FUERA DE PANTALLA · EL ADULTO ACOMPAÑA</p><p>${toddler?'Prepara una pelota grande y blanda adecuada a la edad, en un espacio despejado.':'Prepara un muñeco y una tela grande adecuada al juego, bajo supervisión directa.'}</p><ol class="steps"><li><strong>${toddler?'Invita':'Muestra'}</strong><p>${toddler?'Siéntate cerca y haz rodar la pelota suavemente.':'Haz una secuencia breve: saludar al muñeco y arroparlo.'}</p></li><li><strong>Espera</strong><p>${toddler?'Puede mirar, tocar, empujar o proponerte otra cosa. No hace falta devolver la pelota.':'Invita a imitar o cambiar la historia. Puedes mostrar un paso cada vez.'}</p></li><li><strong>Sigue su iniciativa</strong><p>${toddler?'Nombra lo que ocurre y deja que proponga el siguiente turno.':'Pregunta «¿y ahora qué?» y da tiempo para responder con gestos o palabras.'}</p></li></ol><p class="notice">Guarda la pantalla durante el juego. Usa materiales seguros, sin piezas pequeñas, y supervisión directa. Si aparece cansancio, frustración o pierde interés, simplifica o para.</p><div class="reflection"><h4>Para observar, sin examinar</h4><p>${toddler?'¿Qué captó su interés? ¿Cómo te invitó a continuar?':'¿Qué parte eligió repetir o cambiar? ¿Qué ayuda le resultó útil?'}</p><p>No hace falta registrar respuestas ni completar todos los pasos.</p></div><div class="controls"><button type="button" class="action primary" id="offline-start">Listo, vamos a jugar sin pantalla</button></div>`;on('offline-start','click',()=>transition('finish'));}

function catalogMarkup(){
 const base=stages.find(s=>s.id===stage),rows=entriesFor(stage,selectedArea);
 return `<nav class="activity-catalog" aria-label="Propuestas de ${base.label}"><p class="eyebrow">03 · ABRE UNA PROPUESTA</p><p class="catalog-count">${rows.length} ${rows.length===1?'propuesta disponible':'propuestas disponibles'} · ${selectedArea==='all'?'Todas las áreas':selectedArea}</p>${rows.length?`<div class="catalog-grid">${rows.map(a=>`<button type="button" class="catalog-card" data-activity="${a.id}" aria-pressed="${(selectedActivities[stage]||'original')===a.id}" aria-controls="activity"><span class="catalog-area">${a.area} · ${typeLabel(a.type)}</span><strong>${languageFor(a.id)?languageFor(a.id).name+' · ':''}${a.unit}</strong><span>${a.goal}</span><small>${a.id==='words'?'Piloto 7–8 años · ':''}${a.duration} · ${statusLabel(states[a.key]?.phase)}</small></button>`).join('')}</div>`:`<div class="empty-area"><h4>Aún no hay propuestas en esta combinación.</h4><p>Puedes ver las áreas disponibles para ${base.label} o elegir otra etapa. No hace falta completar nada para acceder.</p><button type="button" class="action secondary" id="all-areas">Ver todas las áreas de esta etapa</button></div>`}<p class="quiet">Orden editorial opcional, no currículo validado. Cambiar de propuesta conserva tus elecciones, salvo en Dani: sus decisiones narrativas se descartan al salir. El aviso superior indica si también se guardaron en este navegador.</p></nav>`;
}
function bindCatalog(){on('all-areas','click',()=>{selectedArea='all';renderAreas();renderPanel();focus('area-select');});document.querySelectorAll('[data-activity]').forEach(b=>b.addEventListener('click',()=>{selectedActivities[stage]=b.dataset.activity;states[stateKey()]??=fresh();if(['garden','words'].includes(b.dataset.activity))current().gardenFocus=true;renderPanel();focus('session-title');}));}
function renderExtra(){
 const st=current(),activity=extraActivities[stage],q=activity.steps[st.extraStep];
 document.querySelector('#exercise').innerHTML=`<div class="question-head"><span class="pill">Idea ${st.extraStep+1} de ${activity.steps.length}</span><span class="quiet">Puedes cerrar cuando quieras</span></div><div class="scenario"><p id="extra-context">${q.context}</p>${stage==='3y'?'<div class="pattern-row" aria-hidden="true">'+(st.extraStep===0?['●','▲','●','▲','?']:['👏','👏','🙌','👏','👏','?']).map(symbol=>`<span>${symbol}</span>`).join('')+'</div>':''}${stage==='5y'?'<div class="route-grid" role="img" aria-label="Cuadrícula: fila superior A1, B1, C1; fila central A2, B2, C2; fila inferior A3, B3, C3. Inicio A1 y destino C2.'+(st.extraStep===1?' B1 está bloqueada.':'')+'">'+['A1','B1','C1','A2','B2','C2','A3','B3','C3'].map(c=>`<span class="${c==='A1'?'route-start':c==='C2'?'route-end':''}">${c}${c==='A1'?' · Inicio':c==='C2'?' · Meta':c==='B1'&&st.extraStep===1?' · Bloqueada':''}</span>`).join('')+'</div>':''}</div><fieldset aria-describedby="extra-context"><legend id="extra-question" tabindex="-1" aria-describedby="extra-context">${q.title}</legend><div class="answer-options">${q.options.map(([id,label])=>`<button type="button" class="answer-option" data-extra-answer="${id}" aria-pressed="${st.extraChoice===id}">${label}</button>`).join('')}</div></fieldset><div class="controls"><button type="button" class="action primary" id="check-extra">Revisar mi idea</button><button type="button" class="action secondary" id="extra-hint">${st.hintLevel===q.hints.length?'Releer la pista':st.hintLevel?'Otra pista':'Una pista'}</button></div><div id="hint-feedback" class="hint-feedback" role="status" aria-live="polite" aria-atomic="true">${st.hintLevel?q.hints[st.hintLevel-1]:''}</div>${feedbackMarkup()}<div class="controls"><button type="button" class="action secondary" id="next-extra" ${st.extraCorrect&&st.extraStep<activity.steps.length-1?'':'hidden'}>Opcional: probar la siguiente idea →</button></div>${closeMarkup()}<p class="quiet">Puedes explicar tu idea hablando, señalando o dibujando. No grabamos explicaciones personales.</p>`;
 document.querySelectorAll('[data-extra-answer]').forEach(b=>b.addEventListener('click',()=>{st.extraChoice=b.dataset.extraAnswer;st.extraCorrect=false;document.querySelectorAll('[data-extra-answer]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelector('#next-extra').hidden=true;showClose(false);feedback('');}));
 on('check-extra','click',()=>{if(!st.extraChoice){feedback('Elige una idea para revisarla. Puedes pedir una pista.');return;}const result=checkActivityAnswer(stage,st.extraStep,st.extraChoice);st.extraCorrect=result.correct;feedback(result.feedback);document.querySelector('#next-extra').hidden=!result.correct||st.extraStep===activity.steps.length-1;showClose(result.correct);});
 on('extra-hint','click',()=>{st.hintLevel=Math.min(st.hintLevel+1,q.hints.length);document.querySelector('#hint-feedback').textContent=q.hints[st.hintLevel-1];document.querySelector('#extra-hint').textContent=st.hintLevel===q.hints.length?'Releer la pista':'Otra pista';});
 on('next-extra','click',()=>{st.extraStep++;st.extraChoice=null;st.extraCorrect=false;st.hintLevel=0;st.feedback='';st.success=false;renderExtra();focus('extra-question');document.getElementById('extra-context')?.scrollIntoView?.({block:'start'});});bindFinish();
}

function facilitationMarkup(){
 if(Object.hasOwn(scienceGames,selectedActivities[stage]))return '<p class="quiet">Lectura acompañada orientativa para 6–8 años. Señala una evidencia del registro y pregunta qué permite concluir. No hacen falta pruebas con materiales ni tocar seres vivos. Puedes pasar o parar.</p>';
 if(selectedActivities[stage]==='reflection')return '<p class="quiet">Con adulto acompañante. Puedes explorar sin responder; no pedimos ni guardamos sentimientos personales.</p>';
 if(languageFor(selectedActivities[stage]))return '<p class="quiet">Piloto escrito acompañado para 6–8 años, también explorable por lectores principiantes mayores. Para menores, el adulto puede nombrar objetos reales fuera de pantalla; no se ofrece una sesión digital infantil de idiomas.</p>';
 if(selectedActivities[stage]==='words')return current().phase==='intro'?'<p class="quiet">Piloto 7–8 años. Lectura acompañada disponible; la adaptación a seis años está pendiente de probar. Puedes tocar pistas y explicar con gestos, sin grabación.</p>':'';
 if(selectedActivities[stage]==='garden')return current().phase==='intro'?'<p class="quiet">Acompañamiento opcional dentro del juego: una ayuda breve para cada parte. Puedes señalar y otra persona pulsar.</p>':'';
 const guide=getFacilitation(stage,selectedActivities[stage]==='unit'?'extra':selectedActivities[stage]||'original');
 return `<details class="facilitation"><summary>Ideas para acompañar y ajustar la ayuda</summary><p>Guía opcional para quien acompaña; también puedes consultarla por tu cuenta. No hace falta completar estos pasos.</p><dl><dt>Un ejemplo antes de probar</dt><dd>${guide.model}</dd><dt>Si hace falta más apoyo</dt><dd>${guide.support}</dd><dt>Cuando puedes retirar ayuda</dt><dd>${guide.fade}</dd><dt>Para conversar, sin examinar</dt><dd>${guide.observe}</dd></dl><p>Adapta los gestos y usa la lengua y la forma de comunicación que les resulten cómodas. Puedes parar, cambiar de propuesta o continuar fuera de pantalla. Estas ideas no evalúan capacidades ni sustituyen apoyos individuales.</p></details>`;
}

