on('open-words','click',()=>{selectedArea='all';renderAreas();stage='5y';selectedActivities[stage]='words';states[stateKey()]??=fresh();current().gardenFocus=true;renderStages();renderPanel();focus('session-title');});

// Local-only progress. No network, account, identifier or free-text child input.
let progressStorage;
try{progressStorage=document.defaultView.localStorage;}catch{}
const progressSession=createProgressSession(progressStorage,{locks:document.defaultView.navigator.locks});
let progressResult=progressSession.reload();
let progressConfirm=false,progressOpen=false,progressReloadConfirm=false;
if(progressResult.ok){stage=progressResult.snapshot.stage;Object.assign(states,progressResult.snapshot.states);Object.assign(selectedActivities,progressResult.snapshot.selectedActivities);}
function progressMessage(){
 const status=progressResult.status;
 if(status==='conflict')return 'Otra pestaña cambió el progreso. Hemos detenido el guardado aquí para no sobrescribirlo.';
 if(status==='saving')return 'Guardando en este navegador…';
 if(progressResult.operation==='clear'&&!progressResult.ok)return 'No se pudo borrar. Tu progreso sigue aquí; puedes reintentarlo.';
 if(status==='loaded')return 'Recuperamos tu progreso en este navegador.';
 if(status==='saved')return 'Guardado en este navegador.';
 if(status==='cleared')return 'Progreso borrado de este navegador.';
 if(status==='empty')return 'Tu progreso se guardará solo en este navegador.';
 if(['corrupt','unsupported-version','too-large'].includes(status))return 'Hay un guardado que no podemos abrir. No lo hemos sustituido.';
 return 'No se pudo guardar. Puedes seguir, pero al cerrar podrías perder los cambios.';
}
function renderProgress(){
 const root=document.querySelector('#local-progress');
 const conflict=progressResult.status==='conflict';
 const failed=!progressResult.ok&&!['empty','saving'].includes(progressResult.status);
 root.classList.toggle('progress-warning',failed);
 root.innerHTML=`<div class="progress-line"><p id="progress-status" tabindex="-1" role="status" aria-live="polite">${progressMessage()}</p><button type="button" class="progress-toggle" id="progress-options" aria-expanded="${progressOpen}" aria-controls="progress-details">${progressOpen?'Cerrar opciones':'Guardado y privacidad'}</button></div>${conflict?`<div class="progress-conflict"><p>Tus elecciones actuales siguen visibles en esta pestaña, pero no se guardarán. Puedes revisarlas antes de cargar lo guardado por la otra pestaña.</p>${progressReloadConfirm?'<p><strong>Cargar sustituirá las elecciones visibles aquí por el último guardado.</strong> Si se borró desde otra pestaña, volverás al inicio.</p><button type="button" class="action secondary" id="progress-load-confirm">Sí, cargar el último guardado</button><button type="button" class="action secondary" id="progress-load-cancel">Seguir revisando aquí</button>':'<button type="button" class="action secondary" id="progress-load">Cargar el último guardado</button>'}</div>`:''}<div id="progress-details" ${progressOpen?'':'hidden'}><p>Este dispositivo recuerda la propuesta y sus elecciones, sin nombres, perfiles ni datos personales. No se envían a un servidor. En un dispositivo compartido, otra persona que abra esta app puede verlas. No hay sincronización ni copia de seguridad; el navegador puede borrar su almacenamiento.</p>${progressResult.coordination==='optimistic'?'<p>Este navegador no ofrece coordinación completa entre pestañas. Usa una sola pestaña para evitar cambios simultáneos.</p>':''}<p>Si recuperas una respuesta sin su explicación, pulsa «Revisar» para verla de nuevo.</p>${failed&&!conflict?'<p>El guardado anterior se conserva si existe. Puedes reintentar; si está dañado o es de otra versión, solo se sustituirá después de borrarlo voluntariamente.</p><button type="button" class="action secondary" id="progress-retry">Reintentar guardado</button>':''}<div class="progress-delete" ${conflict?'hidden':''}>${progressConfirm?'<p><strong>¿Borrar el progreso de todas las propuestas en este navegador?</strong> Esta acción no se puede deshacer. No afecta otros datos del navegador.</p><button type="button" class="action secondary" id="progress-delete-confirm">Sí, borrar el progreso</button><button type="button" class="action secondary" id="progress-delete-cancel">Conservarlo</button>':'<button type="button" class="action secondary" id="progress-delete">Borrar progreso de este navegador</button>'}</div></div>`;
 on('progress-options','click',()=>{progressOpen=!progressOpen;progressConfirm=false;renderProgress();focus('progress-options');});
 on('progress-delete','click',()=>{progressConfirm=true;renderProgress();focus('progress-delete-cancel');});
 on('progress-delete-cancel','click',()=>{progressConfirm=false;renderProgress();focus('progress-delete');});
 on('progress-delete-confirm','click',()=>settleProgress(progressSession.clear(),result=>{progressResult={...result,operation:"clear"};if(result.ok){Object.keys(states).forEach(k=>delete states[k]);Object.keys(selectedActivities).forEach(k=>delete selectedActivities[k]);stage=null;progressConfirm=false;renderStages();renderPanel();}renderProgress();focus(result.ok?'stage-title':'progress-status');}));
 on('progress-load','click',()=>{progressReloadConfirm=true;renderProgress();focus('progress-load-cancel');});
 on('progress-load-cancel','click',()=>{progressReloadConfirm=false;renderProgress();focus('progress-load');});
 on('progress-load-confirm','click',()=>{const result=progressSession.reload();progressResult=result;progressReloadConfirm=false;if(result.ok||result.status==='empty'){Object.keys(states).forEach(k=>delete states[k]);Object.keys(selectedActivities).forEach(k=>delete selectedActivities[k]);stage=result.ok?result.snapshot.stage:null;if(result.ok){Object.assign(states,result.snapshot.states);Object.assign(selectedActivities,result.snapshot.selectedActivities);}renderStages();renderPanel();}renderProgress();focus('progress-status');});
 on('progress-retry','click',()=>{if(stage)persistProgress();else{progressResult=progressSession.inspect();renderProgress();}focus('progress-status');});
}
function settleProgress(result,done){if(result&&typeof result.then==='function'){progressResult={ok:false,status:'saving'};renderProgress();result.then(value=>{if(value.status!=='superseded')done(value);}).catch(()=>{progressResult={ok:false,status:'unavailable'};renderProgress();});}else done(result);}
function persistProgress(){if(!stage)return;settleProgress(progressSession.save({stage,selectedActivities,states}),result=>{progressResult=result;renderProgress();});}
document.defaultView.addEventListener('storage',event=>{if(event.key===PROGRESS_KEY||event.key===null){const result=progressSession.inspect();if(!result.ok&&result.status!=='empty'){progressResult=result;renderProgress();}}});

document.querySelector('a[href="#principios"]').addEventListener('click',()=>{if(stage)current().gardenFocus=false;document.body.classList.remove('garden-focus');});
renderAreas();renderStages();renderPanel();renderProgress();
for(const type of ['click','change']){document.addEventListener(type,event=>{event.progressControl=!!event.target.closest('#local-progress, #companion');},true);document.addEventListener(type,event=>{if(!event.progressControl)persistProgress();});}

function openRoute(key){
 const entry=catalog.find(a=>a.key===key);if(!entry)return;
 stage=entry.stage;selectedArea='all';selectedActivities[stage]=entry.id;states[key]??=fresh();
 renderAreas();renderStages();renderPanel();focus('session-title');document.querySelector('#activity')?.scrollIntoView?.({block:'start'});
}
document.querySelector('#language-routes').innerHTML=languages.map(l=>`<article class="route-card"><p class="eyebrow" lang="${l.id}">${l.native}</p><h3>${l.name}</h3><p>Palabras cercanas</p><p class="quiet">Piloto escrito · 3 palabras · 6–8 años con acompañamiento</p><button type="button" class="action secondary" data-route="5y:language-${l.id}">Explorar ${l.name}</button></article>`).join('');
document.querySelector('#discipline-routes').innerHTML=disciplines.map(d=>`<article class="route-card" id="discipline-${d.id}"><p class="eyebrow">${d.area}</p><h3>${d.name}</h3><span class="pill">${d.status}</span><p>${d.scope}</p><p class="quiet">${d.note}</p>${d.entries.map(([key,label])=>`<button type="button" class="action secondary" data-route="${key}">${label}</button>`).join('')}</article>`).join('');
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>openRoute(b.dataset.route)));
document.querySelectorAll('.explore-nav a').forEach(a=>a.addEventListener('click',()=>{if(a.getAttribute('href')==='#companion'){const dock=document.querySelector('#activity-companion');if(dock)dock.open=true;focus('companion-title');return;}if(stage)current().gardenFocus=false;document.body.classList.remove('garden-focus');document.querySelector(a.getAttribute('href')+' h2')?.focus();}));

companionController=mountCompanion(companionRoot,()=>{
 if(!stage)return 'Elige una historia o un idioma. Puedes mirar primero y pedir ayuda a un adulto.';
 if(current().phase==='paused')return 'La actividad está en pausa. Puedes descansar o volver cuando quieras; no hay nada que recuperar.';
 if(current().phase==='finished')return 'La sesión ya está cerrada. Puedes llevar la idea al papel o dejarlo aquí por hoy.';
 const id=selectedActivities[stage];
 if(Object.hasOwn(scienceGames,id))return scienceGames[id].name+': '+scienceGames[id].steps[current().science?.step??0].hint;
 if(id==='reflection')return 'La torre de Dani: no sabemos con certeza qué siente. Piensa en dos posibilidades y qué parte de la historia las apoya. También puedes pasar.';
 const lang=languageFor(id);if(lang)return lang.name+': consulta las tres palabras antes de elegir. '+lang.words[0]+' significa gato. Las etiquetas españolas junto a los dibujos también ayudan. No hace falta pronunciarlas.';
 if(selectedStage().kind==='offline')return 'Esta guía es para el adulto. Lee la propuesta y aparta la pantalla; sigue el interés del pequeño con objetos seguros.';
 if(id==='garden')return 'En el jardín, sigue las flechas una por una. Mira dónde termina cada paso; puedes deshacerlo y volver a probar.';
 if(id==='words')return 'En La palabra escondida, busca qué palabras de la escena aclaran el significado. Una pista del texto puede cambiar tu primera idea.';
 if(id==='unit')return 'Al comparar, cambia una sola condición y observa qué mantienes igual. Puedes consultar el ejemplo de la unidad.';
 return 'En «'+selectedStage().unit+'», relee la pregunta y busca la pista dentro del reto. Explica una razón, hablando o señalando; no hace falta acertar a la primera.';
},progressStorage);
